mapper.select:
SELECT

FROM spd_data_audit a
WHERE a.del_flag = #{delFlag}

    AND a.audit_type = #{query.auditType}


    AND a.target_name LIKE CONCAT('%', #{query.targetName}, '%')


    AND a.audit_status = #{query.auditStatus}


    AND a.submit_user = #{query.submitUser}


    AND a.submit_time >= #{query.submitTimeStart}


    AND a.submit_time <= #{query.submitTimeEnd}

ORDER BY a.submit_time DESC
